export const meta = {
  name: 'vliw-sparse-mask-search',
  description: 'Parallel sparse-mask combinatorial search over VLIW list-scheduler levers (D3_GATHER_MASK / D4_COLD_MASK / const_flow) with a correctness + cycle-count no-regress gate.',
  when_to_use: 'Use for a standalone Python VLIW instruction-scheduler kernel (KernelBuilder.build_kernel) where the score is emitted instruction-bundle count (cycles). Fans out per-instance emit-order mask probes across cores, then combo-searches the benefit window, landing only masks that beat the current best without regressing the PSPACE=0 gate. The single technique is instruction_scheduling: it does not rewrite the kernel algebra, only which emit-order instances route mux<->gather / const<->flow.',
  phases: [
    { title: 'Single-position sweep', detail: 'probe every emit-order position for the mask lever, collect realized cycles + engine floors' },
    { title: 'Combo search', detail: 'fan out pair/triple combinations over the non-regressing / benefit-window positions' },
    { title: 'Verify + land', detail: 'run parity + algebra + submission_tests + PSPACE=0 gate on the best mask' },
  ],
}

// args contract (all optional except probe_cmd / verify_cmd):
//   probe_cmd        : shell template that runs one mask build and prints "realized=N load=.. alu=.. valu=.. flow=.."
//                      the template must contain the token {MASK} where the JSON 0/1 list is substituted.
//   verify_cmd       : shell that runs parity + algebra + submission_tests and prints the landed cycle count + PASS/FAIL.
//   n_positions      : emit-order length (default 64)
//   baseline_cycles  : current best to beat (gate: strictly less)
//   pspace0_gate     : max allowed PSPACE=0 cycles (must not regress)
//   combo_sizes      : array of combination sizes to search (default [2,3])
//   exp_dir          : run dir for artifacts

const N = args.n_positions || 64
const BASE = args.baseline_cycles || 1134
const SIZES = args.combo_sizes || [2, 3]

const SWEEP_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['pos', 'realized'],
        properties: {
          pos: { type: 'integer' },
          realized: { type: 'integer' },
          load: { type: 'number' },
          alu: { type: 'number' },
          valu: { type: 'number' },
          flow: { type: 'number' },
        },
      },
    },
  },
}

const COMBO_SCHEMA = {
  type: 'object',
  required: ['best'],
  properties: {
    best: {
      type: 'array',
      items: {
        type: 'object',
        required: ['mask', 'realized'],
        properties: {
          mask: { type: 'array', items: { type: 'integer' } },
          realized: { type: 'integer' },
        },
      },
    },
  },
}

const VERIFY_SCHEMA = {
  type: 'object',
  required: ['landed_cycles', 'pspace0_cycles', 'parity_pass', 'algebra_pass'],
  properties: {
    landed_cycles: { type: 'integer' },
    pspace0_cycles: { type: 'integer' },
    parity_pass: { type: 'boolean' },
    algebra_pass: { type: 'boolean' },
    verdict: { type: 'string' },
  },
}

// ---- Phase 1: single-position sweep, fanned out in shards -----------------
phase('Single-position sweep')
const SHARDS = Math.min(14, N)
const per = Math.ceil(N / SHARDS)
const shardRanges = []
for (let s = 0; s < SHARDS; s++) {
  const lo = s * per
  const hi = Math.min(N, lo + per)
  if (lo < hi) shardRanges.push([lo, hi])
}

const sweepShards = await parallel(shardRanges.map(([lo, hi]) => () =>
  agent(
    `You are sweeping single-position sparse-mask probes for a VLIW list-scheduler.\n` +
    `For each position p in [${lo}, ${hi}), build a length-${N} 0/1 mask with only p set,\n` +
    `run this exact probe command (substitute the JSON list for {MASK}):\n\n${args.probe_cmd}\n\n` +
    `Parse the printed "realized=N load=.. alu=.. valu=.. flow=.." line for each p.\n` +
    `Return every position's realized cycle count and engine floors. Do not guess — run the command.`,
    { label: `sweep:${lo}-${hi}`, phase: 'Single-position sweep', schema: SWEEP_SCHEMA }
  )
))

const sweep = sweepShards.filter(Boolean).flatMap(r => r.results)
sweep.sort((a, b) => a.realized - b.realized)
log(`sweep done: ${sweep.length} positions; best single = ${sweep[0]?.realized} vs base ${BASE}`)

// benefit window = positions whose single-mask realized is closest to / below base
const window = sweep.filter(r => r.realized <= BASE + 20).map(r => r.pos)
const searchPositions = (window.length >= 2 ? window : sweep.slice(0, 12).map(r => r.pos))

// If not even a single position is non-regressing AND the window is tiny, still try combos
// (E2 showed sparse combos can win where singles regress).

// ---- Phase 2: combo search over the benefit window ------------------------
phase('Combo search')
const comboAgents = []
for (const size of SIZES) {
  comboAgents.push(() => agent(
    `Combinatorial sparse-mask search for a VLIW scheduler. Candidate emit-order positions:\n` +
    `${JSON.stringify(searchPositions)}\n` +
    `Enumerate all size-${size} combinations. For each, build a length-${N} 0/1 mask with those\n` +
    `positions set and run (substitute JSON list for {MASK}):\n\n${args.probe_cmd}\n\n` +
    `Parse realized cycles. Return the top masks by lowest realized (at least those <= ${BASE}).\n` +
    `Run every command; do not estimate.`,
    { label: `combo:size${size}`, phase: 'Combo search', schema: COMBO_SCHEMA }
  ))
}
const comboResults = (await parallel(comboAgents)).filter(Boolean).flatMap(r => r.best)
comboResults.sort((a, b) => a.realized - b.realized)

const candidates = comboResults.filter(c => c.realized < BASE)
log(`combo search: ${comboResults.length} evaluated, ${candidates.length} beat base ${BASE}`)

if (!candidates.length) {
  return {
    overall_speedup: null,
    best_cycles: sweep[0]?.realized ?? null,
    baseline_cycles: BASE,
    landed: false,
    note: `No mask beat baseline ${BASE}. Best combo=${comboResults[0]?.realized ?? 'n/a'}, best single=${sweep[0]?.realized ?? 'n/a'}. Lever appears to add work to the binding engine (no drain-window hole found).`,
    sweep,
  }
}

// ---- Phase 3: verify + land the best candidate ----------------------------
phase('Verify + land')
const best = candidates[0]
const verify = await agent(
  `Verify a candidate VLIW schedule mask before landing. The winning mask is:\n` +
  `${JSON.stringify(best.mask)}\n(probe reported realized=${best.realized}).\n` +
  `Set the mask via the same env var used in the probe command, then run the full gate:\n\n${args.verify_cmd}\n\n` +
  `Report the landed cycle count (PSPACE=1), the PSPACE=0 cycle count, and whether parity\n` +
  `and algebra checks pass. verdict = "LAND" only if landed_cycles < ${BASE}, pspace0 <= ${args.pspace0_gate || 1187},\n` +
  `parity and algebra both pass; otherwise "REJECT".`,
  { label: 'verify:best', phase: 'Verify + land', schema: VERIFY_SCHEMA }
)

const landed = verify.verdict === 'LAND' &&
  verify.landed_cycles < BASE &&
  verify.pspace0_cycles <= (args.pspace0_gate || 1187) &&
  verify.parity_pass && verify.algebra_pass

return {
  overall_speedup: landed ? BASE / verify.landed_cycles : null,
  best_cycles: verify.landed_cycles,
  baseline_cycles: BASE,
  landed,
  best_mask: best.mask,
  pspace0_cycles: verify.pspace0_cycles,
  verify,
  note: landed
    ? `Landed mask beating ${BASE}: ${verify.landed_cycles} cycles (PSPACE=0 ${verify.pspace0_cycles}).`
    : `Best mask failed the land gate (landed=${verify.landed_cycles}, pspace0=${verify.pspace0_cycles}).`,
  sweep,
}

