export const meta = {
  name: 'vliw-anneal-optimizer',
  description: 'Landability-gated simulated annealing over per-instruction VLIW engine-assignment masks for a Python VLIW list-scheduler kernel (minimizes scheduled cycle count; arithmetic-identity-preserving by construction).',
  whenToUse: 'When optimizing a Python VLIW list-scheduler kernel whose objective is scheduled cycle count, and the search space is per-instruction engine-assignment masks (combine/extract/offset/const_flow/xor genes). Re-seeds SA fresh from the current graph heuristic, optimizes the single-rotation oracle proxy, and ships only champs that pass the dual landability gate (PSPACE=1 correct AND <best AND PSPACE=0 correct AND <=1187). NOT for GPU/CUDA kernel generation.',
  phases: [
    { title: 'Orient', detail: 'Read directions/LESSONS.md (do-not-repeat registry) and measure current baseline cycles via the submission test gate (PSPACE=1 and PSPACE=0)' },
    { title: 'Anneal', detail: 'Dispatch agent to run omni_anneal.py (and optionally joint_floor_anneal.py) with bounded iters, re-seeded fresh; select the best correct+landable champ genome' },
    { title: 'Verify', detail: 'Run verify_champ.py dual landability gate (PSPACE=1 < best AND PSPACE=0 <=1187); report landable cycle count + genome; non-removable gate' },
  ],
  requiredSkills: [],
  optionalSkills: [],
  skill_binding_mode: 'prompt_reference_only',
}

// __modelTierApplied (declaration pre-existing)

const WORKFLOW_NAME = 'vliw-anneal-optimizer'

// --- BEGIN inlined arg_guard (Workflow runtime parses scripts as bare scripts,
//                              not ES modules; static imports are rejected) ---
function __unwrapArgs(rawArgs) {
  if (rawArgs == null) return {}
  if (typeof rawArgs === 'object' && !Array.isArray(rawArgs)) return rawArgs
  if (typeof rawArgs === 'string') {
    const trimmed = rawArgs.trim()
    if (trimmed === '') return {}
    if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
      try {
        const parsed = JSON.parse(trimmed)
        if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) return parsed
        throw new Error('arg_guard: parsed JSON value is not a plain object')
      } catch (e) { throw new Error(`arg_guard: invalid JSON args: ${e.message}`) }
    }
    const out = {}
    const re = /(\w[\w.-]*)=("(?:\\\\\"|[^"])*"|\'(?:\\\\\'|[^\'])*\'|\S+)/g
    let m
    while ((m = re.exec(trimmed)) !== null) {
      let v = m[2]
      if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
        v = v.slice(1, -1)
      }
      out[m[1]] = v
    }
    if (Object.keys(out).length === 0) {
      throw new Error(`arg_guard: workflow args is a non-empty string but contains no key=value pairs and is not JSON. First 160 chars: ${trimmed.slice(0, 160)}`)
    }
    return out
  }
  throw new Error(`arg_guard: workflow args has unexpected type: ${typeof rawArgs}`)
}
// eslint-disable-next-line no-global-assign
args = __unwrapArgs(typeof args === 'undefined' ? undefined : args)
// --- END inlined arg_guard ---

// --- BEGIN inlined agent-retry scaffolding (from _meta/scaffolding/agent-retry.js) ---
async function agentRetry(fn, opts) {
  const retries = (opts && opts.retries != null) ? opts.retries : 5
  let lastError = null
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const result = await fn()
      if (result != null) return result
    } catch (e) {
      lastError = e
    }
  }
  if (lastError) throw lastError
  if (opts && opts.allowNull === true) return null
  throw new Error(
    `agentRetry: "${(opts && opts.label) || 'agent'}" returned null after ${retries + 1} attempt(s) ` +
    `(agent skipped or terminal API failure after retries).`,
  )
}

function expect(obj, field, ctx) {
  if (obj == null || obj[field] == null) {
    throw new Error(
      `agentRetry: required field "${field}" is missing${ctx ? ' from ' + ctx : ''} ` +
      `(agent returned null or a malformed result after retries).`,
    )
  }
  return obj[field]
}

function guard(obj, field, fallback) {
  if (obj == null || obj[field] == null) return fallback
  return obj[field]
}
// --- END inlined agent-retry scaffolding ---

// =============================================================================
// vliw-anneal-optimizer — single-technique workflow (probation)
// =============================================================================
//
// Technique (ONE, canonical id = "instruction_scheduling"):
//   "Landability-gated simulated annealing over per-instruction VLIW
//    engine-assignment masks."
//
// Faithful to the local-tool reality of the vliw-w6-omni worktree. The solver
// orchestrates EXISTING Python scripts via Bash — it does NOT generate GPU
// kernels, does NOT invoke a GPU profiler, and uses no wall-clock or PRNG host
// APIs. All randomness lives inside the Python annealers (seeded).
//
// Local tools (already exist in the worktree):
//   - experiments/omni_anneal.py        SA over combine/extract/offset masks
//   - experiments/joint_floor_anneal.py joint load+alu floor drop (const_flow/xor/...)
//   - experiments/verify_champ.py       dual landability gate (exit 0 iff landable)
//   - tests/submission_tests.py         prints "CYCLES: N"; PSPACE env selects config
//   - directions/LESSONS.md             do-not-repeat registry (MUST read first)
//
// Dual landability gate (NON-REMOVABLE — the key correctness insight):
//   A win on the primary metric (PSPACE=1 cycles) that regresses the secondary
//   configuration (PSPACE=0) is NOT landable. verify_champ.py encodes:
//     exit 0  iff  PSPACE=1 correct AND c1 < best AND PSPACE=0 correct AND c0 <= 1187
//
// Usage:
//   Workflow({name: 'vliw-anneal-optimizer', args: {
//     project_root: '/mnt/.../vliw-w6-omni',   // worktree with the 1134 graph
//     iters: 8000,                               // SA iterations (bounded)
//     classes: 'combine,extract,offset',         // SA gene classes
//     joint_floor: false,                        // also run joint_floor_anneal.py
//     exp_dir: '/tmp/vliw_anneal_exp',           // scratch for champ.json etc.
//   }})
//
// =============================================================================

const PROJECT_ROOT = args.project_root || '.'
const EXP_DIR = args.exp_dir || '/tmp/vliw_anneal_exp'
const ITERS = args.iters || 8000
const CLASSES = args.classes || 'combine,extract,offset'
const JOINT_FLOOR = args.joint_floor === true || args.joint_floor === 'true'
const SEED = args.seed || null  // pass-through; null = let omni_anneal default (2028)
const BEST_KNOWN = args.best_known || 1134      // current global best (PSPACE=1)
const PSPACE0_BOUND = args.pspace0_bound || 1187 // secondary-config regression bound

if (!PROJECT_ROOT) {
  throw new Error('vliw-anneal-optimizer: args.project_root is required (path to the vliw worktree)')
}

// Model routing by agent role
const MODEL = {
  mechanical: args.model_mechanical || 'haiku',  // runs shell, parses output
  judgment: args.model_judgment || 'sonnet',     // planning + final report
}

const JSON_PASSTHROUGH = { type: 'object', additionalProperties: true }

// State
let baselineCycles = null
let baselinePspace0 = null
let lessonsDigest = ''
let champGenome = null            // the genome JSON object (best landable)
let champCycles = null            // PSPACE=1 cycles of the champ
let champPspace0Cycles = null     // PSPACE=0 cycles of the champ
let champPath = ''                // path to champ.json on disk
let bestKernelCode = ''           // serialized genome (the "kernel" = engine masks)
let landable = false

// =============================================================================
// Phase 1: Orient — read LESSONS.md + measure current baseline cycles
// =============================================================================
phase('Orient')

const orient = await agentRetry(() => agent(`You are orienting a VLIW instruction-scheduler optimization run. Work inside the project worktree at ${PROJECT_ROOT}.

# Step 1 — Read the do-not-repeat registry (MANDATORY first)
Read ${PROJECT_ROOT}/directions/LESSONS.md in full. Extract:
- the current global best cycle count (PSPACE=1) and the PSPACE=0 bound,
- the binding-engine floor hierarchy (load/alu/valu/flow),
- every "verified kill" entry with its ID, measured result, and resurrection condition,
- any rule about mandatory re-anneal after op-count changes (Rule C).

# Step 2 — Measure the current baseline cycles for BOTH configurations
Run from ${PROJECT_ROOT} (these are the canonical gates):
  1. \`cd ${PROJECT_ROOT} && python parity_check.py && python algebra_check_ported.py && python tests/submission_tests.py\`
     -> capture the line that prints "CYCLES: N" (this is PSPACE=1).
  2. \`cd ${PROJECT_ROOT} && PSPACE=0 python tests/submission_tests.py\`
     -> capture "CYCLES: N" (this is PSPACE=0).

If any command fails, report the failure verbatim and return success=false.

Return a JSON object with:
- lessons_digest: a concise string of the binding floors + killed directions + Rule C
- baseline_cycles: the PSPACE=1 cycle count (number) or null
- baseline_pspace0_cycles: the PSPACE=0 cycle count (number) or null
- success: boolean
- error: string (only on failure)`, {
  label: 'orient',
  phase: 'Orient',
  model: MODEL.mechanical,
  schema: {
    type: 'object',
    properties: {
      lessons_digest: { type: 'string' },
      baseline_cycles: { type: 'number' },
      baseline_pspace0_cycles: { type: 'number' },
      success: { type: 'boolean' },
      error: { type: 'string' },
    },
    required: ['lessons_digest', 'success'],
  },
}), { retries: 5 })

if (!orient.success) {
  throw new Error(`vliw-anneal-optimizer: baseline gate failed in Orient: ${orient.error || 'unknown'}`)
}
lessonsDigest = orient.lessons_digest
baselineCycles = orient.baseline_cycles != null ? orient.baseline_cycles : BEST_KNOWN
baselinePspace0 = orient.baseline_pspace0_cycles != null ? orient.baseline_pspace0_cycles : PSPACE0_BOUND
log(`Orient: baseline PSPACE=1=${baselineCycles}, PSPACE=0=${baselinePspace0}, best_known=${BEST_KNOWN}`)
log(`LESSONS digest: ${lessonsDigest.slice(0, 200)}`)

// =============================================================================
// Phase 2: Anneal — run SA (re-seeded fresh), select best correct+landable champ
// =============================================================================
phase('Anneal')

// Fresh-seed SA over the engine-assignment masks. NEVER --resume a stale champ
// after an op-count change (LESSONS Rule C). omni_anneal.py ships only correct+
// landable champs internally; we re-verify in Phase 3 via the dual gate.
const seedFlag = SEED != null ? ` --seed ${SEED}` : ''
const champOut = `${EXP_DIR}/champ_omni.json`

const annealResult = await agentRetry(() => agent(`Run the VLIW simulated-annealing solver to produce a landable champ genome. Work inside ${PROJECT_ROOT}.

# Step 1 — Prepare scratch
\`\`\`bash
mkdir -p ${EXP_DIR}
\`\`\`

# Step 2 — Run omni_anneal.py (re-seeded FRESH; do NOT pass --resume)
Run exactly:
\`\`\`bash
cd ${PROJECT_ROOT} && python experiments/omni_anneal.py \\
  --classes ${CLASSES} \\
  --iters ${ITERS}${seedFlag} \\
  --out ${champOut}
\`\`\`
Capture the final reported realized cycle count and the champ path.

${JOINT_FLOOR ? `# Step 2b — Also run the joint floor anneal (const_flow/xor gene classes)
Run exactly:
\`\`\`bash
cd ${PROJECT_ROOT} && python experiments/joint_floor_anneal.py \\
  --classes const_flow,xor,combine,offset \\
  --iters ${ITERS} \\
  --out ${EXP_DIR}/champ_joint.json
\`\`\`
Then pick whichever of ${champOut} / ${EXP_DIR}/champ_joint.json has the lower claimed realized cycle count as the candidate champ (prefer omni on ties).` : '# Step 2b — skipped (joint_floor=false)'}

# Step 3 — Read the selected champ JSON
Read the selected champ file. It contains a "genome" object (combine/extract/offset/const_flow/xor masks) and a "realized" cycle count.

# Hard constraints
- Do NOT edit the champ JSON by hand.
- Do NOT pass --resume (Rule C: re-seed fresh from the current graph).
- Do NOT invent cycles; only report what the solver printed / what the champ JSON says.
- If the solver fails to produce a champ, return success=false with the error verbatim.

Return a JSON object with:
- champ_path: the selected champ file path
- genome: the genome object verbatim (combine/extract/offset/const_flow/xor arrays as present)
- claimed_realized: the realized cycle count claimed by the solver (number) or null
- success: boolean
- error: string (only on failure)`, {
  label: 'anneal',
  phase: 'Anneal',
  model: MODEL.mechanical,
  schema: {
    type: 'object',
    properties: {
      champ_path: { type: 'string' },
      genome: { type: 'object', additionalProperties: true },
      claimed_realized: { type: 'number' },
      success: { type: 'boolean' },
      error: { type: 'string' },
    },
    required: ['champ_path', 'success'],
  },
}), { retries: 5 })

if (!annealResult.success) {
  throw new Error(`vliw-anneal-optimizer: SA solver failed in Anneal: ${annealResult.error || 'unknown'}`)
}
champPath = annealResult.champ_path
champGenome = annealResult.genome || null
const claimedRealized = annealResult.claimed_realized
if (!champGenome) {
  throw new Error(`vliw-anneal-optimizer: champ at ${champPath} has no genome object`)
}
log(`Anneal: champ=${champPath}, claimed_realized=${claimedRealized}, classes=${Object.keys(champGenome).join(',')}`)

// =============================================================================
// Phase 3: Verify — dual landability gate (NON-REMOVABLE)
// =============================================================================
phase('Verify')

// The gate: verify_champ.py exit 0 iff
//   PSPACE=1 correct AND c1 < ${BEST_KNOWN}  AND  PSPACE=0 correct AND c0 <= ${PSPACE0_BOUND}
// A win on PSPACE=1 that regresses PSPACE=0 is NOT landable.
const verifyResult = await agentRetry(() => agent(`Run the DUAL LANDABILITY GATE on the champ genome. This is the non-removable correctness gate. Work inside ${PROJECT_ROOT}.

# Step 1 — Run verify_champ.py
Run exactly:
\`\`\`bash
cd ${PROJECT_ROOT} && python experiments/verify_champ.py ${champPath}
\`\`\`
This script:
- injects the genome into KernelBuilder via direct attribute set (same masks the anneal used),
- runs the REAL submission_tests machine path for PSPACE=1 AND PSPACE=0,
- prints "PSPACE=1: correct=... CYCLES=..." and "PSPACE=0: correct=... CYCLES=...",
- exits 0 iff PSPACE=1 correct AND c1 < ${BEST_KNOWN} AND PSPACE=0 correct AND c0 <= ${PSPACE0_BOUND}.

# Step 2 — Parse the output
Extract:
- pspace1_correct (boolean), pspace1_cycles (number)
- pspace0_correct (boolean), pspace0_cycles (number)
- landable = (exit code 0)

# Hard constraints
- Do NOT modify the champ, the test, or the gate.
- Do NOT relax the bounds. The bound for PSPACE=1 is the current best (${BEST_KNOWN}); for PSPACE=0 it is ${PSPACE0_BOUND}.
- If the gate exits non-zero, the champ is NOT landable — report landable=false with the cycle counts.
- A PSPACE=1 win that regresses PSPACE=0 is a FAIL.

Return a JSON object with:
- pspace1_correct, pspace1_cycles
- pspace0_correct, pspace0_cycles
- landable: boolean (true iff verify_champ.py exited 0)
- exit_code: number
- raw_output: string (last 1000 chars)`, {
  label: 'verify',
  phase: 'Verify',
  model: MODEL.mechanical,
  schema: {
    type: 'object',
    properties: {
      pspace1_correct: { type: 'boolean' },
      pspace1_cycles: { type: 'number' },
      pspace0_correct: { type: 'boolean' },
      pspace0_cycles: { type: 'number' },
      landable: { type: 'boolean' },
      exit_code: { type: 'number' },
      raw_output: { type: 'string' },
    },
    required: ['landable', 'exit_code'],
  },
}), { retries: 5 })

landable = verifyResult.landable === true
champCycles = guard(verifyResult, 'pspace1_cycles', null)
champPspace0Cycles = guard(verifyResult, 'pspace0_cycles', null)
const pspace1Correct = guard(verifyResult, 'pspace1_correct', null)
const pspace0Correct = guard(verifyResult, 'pspace0_correct', null)

log(`Verify: landable=${landable} | PSPACE=1 correct=${pspace1Correct} cycles=${champCycles} (gate < ${BEST_KNOWN}) | PSPACE=0 correct=${pspace0Correct} cycles=${champPspace0Cycles} (gate <= ${PSPACE0_BOUND})`)

// Serialize the genome as the "kernel code" (the engine-assignment masks ARE the
// optimized artifact for this VLIW scheduler — there is no GPU source to emit).
bestKernelCode = champGenome ? JSON.stringify(champGenome) : ''

// overall_speedup: cycle-count ratio (baseline / best). Higher is better. For a
// non-landable champ, overall_speedup is null — we do NOT ship regressions.
let overallSpeedup = null
if (landable && champCycles != null && baselineCycles) {
  overallSpeedup = baselineCycles / champCycles
}

// =============================================================================
// Final report
// =============================================================================
phase('Report')

const report = await agentRetry(() => agent(`Write a concise VLIW anneal optimization report.

# Inputs
- project_root: ${PROJECT_ROOT}
- technique: Landability-gated simulated annealing over per-instruction VLIW engine-assignment masks (canonical: instruction_scheduling)
- baseline PSPACE=1 cycles: ${baselineCycles}
- baseline PSPACE=0 cycles: ${baselinePspace0}
- best_known (PSPACE=1 gate): ${BEST_KNOWN}
- PSPACE=0 regression bound: ${PSPACE0_BOUND}
- SA classes: ${CLASSES}
- SA iters: ${ITERS}
- joint_floor: ${JOINT_FLOOR}

# Champ
- champ_path: ${champPath}
- claimed realized (SA oracle): ${claimedRealized}
- genome classes: ${champGenome ? Object.keys(champGenome).join(', ') : 'n/a'}

# Dual gate result (verify_champ.py)
- landable: ${landable}
- PSPACE=1: correct=${pspace1Correct} cycles=${champCycles}  (gate: correct AND < ${BEST_KNOWN})
- PSPACE=0: correct=${pspace0Correct} cycles=${champPspace0Cycles}  (gate: correct AND <= ${PSPACE0_BOUND})
- exit_code: ${guard(verifyResult, 'exit_code', 'n/a')}

# LESSONS digest (from Orient)
${lessonsDigest}

Write a report covering:
1. Whether the champ is landable and why (cite the dual gate numbers).
2. If NOT landable, name which clause failed (PSPACE=1 correctness / < best / PSPACE=0 correctness / <= bound) and the mechanism (do NOT propose a fix — just report).
3. One-line note on whether the SA oracle's claimed realized matched the machine-verified PSPACE=1 cycle count (discrepancy is signal, not a bug to paper over).
4. Reminder of which killed directions from LESSONS.md are relevant to any future re-anneal.

Do NOT invent numbers. Do NOT propose relaxing the gate.`, {
  label: 'report',
  phase: 'Report',
  model: MODEL.judgment,
}), { retries: 5, allowNull: true })

return {
  baseline_cycles: baselineCycles,
  baseline_pspace0_cycles: baselinePspace0,
  best_known_gate: BEST_KNOWN,
  pspace0_bound: PSPACE0_BOUND,
  champ_path: champPath,
  champ_genome: champGenome,
  claimed_realized: claimedRealized,
  pspace1_correct: pspace1Correct,
  pspace1_cycles: champCycles,
  pspace0_correct: pspace0Correct,
  pspace0_cycles: champPspace0Cycles,
  landable: landable,
  overall_speedup: overallSpeedup,
  best_kernel_code: bestKernelCode,
  report: report,
}

